/* Faint Silk 浅丝 by 落吟 | SullyOS 糯米机白框转换
   一套覆盖私聊、群聊、输入栏、双方气泡、语音和转账。
   保留原作者署名；外链图需要联网。装饰不占触控区域。 */
.sully-chat-root {
  color:#3d2c1f;
  --faint-glass:rgba(239,239,239,.18);
  --faint-edge:rgba(140,140,140,.35);
  --faint-ink:#262626;
  --faint-muted:rgba(38,38,38,.55);
}
.sully-chat-header {
  background:transparent!important;
  border:0!important;
  box-shadow:none!important;
  backdrop-filter:none!important;
  -webkit-backdrop-filter:none!important;
  color:#3d2c1f!important;
  overflow:visible!important;
}
.sully-chat-name {
  color:#3d2c1f!important;
  font-size:18px!important;
  font-weight:600!important;
  line-height:1.25!important;
  max-width:100%;
  overflow-wrap:anywhere;
}
.sully-chat-status {color:rgba(61,44,31,.56)!important;font-size:11px!important;}
.sully-chat-token {color:#705f53!important;background:#ffffff70!important;border:1px solid #8c8c8c38!important;}
.sully-chat-avatar {
  width:50px!important;height:50px!important;
  flex-shrink:0!important;
  border-radius:50%!important;object-fit:cover!important;
  box-shadow:0 0 20px #ffffff26,0 4px 12px #0000000f!important;
}
.sully-chat-back,.sully-chat-trigger {
  width:40px!important;height:40px!important;
  min-width:40px!important;min-height:40px!important;
  flex-shrink:0!important;
  display:inline-flex!important;align-items:center!important;justify-content:center!important;
  padding:8px!important;
  color:#51443c!important;
  background:rgba(255,255,255,.2)!important;
  border:1px solid rgba(255,255,255,.3)!important;
  border-radius:50%!important;
  box-shadow:0 2px 8px #00000010!important;
  backdrop-filter:blur(10px)!important;
  -webkit-backdrop-filter:blur(10px)!important;
}
.sully-chat-buffs button {background:#ffffff7a!important;border:1px solid #8c8c8c38!important;color:#675548!important;}
/* 仅在糯米机真正的居中顶栏布置原作双头像；不覆盖返回/电话/生成按钮。 */
.sully-chat-root:not(.sully-chat-group-root) .sully-chat-header:has(.sully-chat-back.absolute) .sully-chat-avatar {
  transform:translateX(-19px)!important;
}
.sully-chat-root:not(.sully-chat-group-root) .sully-chat-header:has(.sully-chat-back.absolute) .sully-chat-name {
  position:relative!important;
}
.sully-chat-root:not(.sully-chat-group-root) .sully-chat-header:has(.sully-chat-back.absolute) .sully-chat-name::after {
  content:"";
  position:absolute;left:calc(50% + 5px);top:-56px;
  width:50px;height:50px;border-radius:50%;
  background:url("https://i.postimg.cc/DycRKBL9/image.jpg") center/cover no-repeat;
  box-shadow:0 2px 12px #0000001a;
  pointer-events:none;
}
.sully-chat-root:not(.sully-chat-group-root) .sully-chat-header:has(.sully-chat-back.absolute) .sully-chat-name::before {
  content:"✩₊행복손에 닿을 듯 가깝다.*✩";
  display:block;margin:1px auto 2px;
  color:rgba(61,44,31,.46);
  font:italic 10px/1.15 Georgia,"Noto Serif SC",serif;
  letter-spacing:.2px;white-space:nowrap;
  pointer-events:none;
}
.sully-chat-inputbar {
  background:rgba(255,255,255,.15)!important;
  color:var(--faint-ink)!important;
  border:0!important;
  border-radius:30px 30px 0 0!important;
  box-shadow:none!important;
  backdrop-filter:blur(20px) saturate(180%)!important;
  -webkit-backdrop-filter:blur(20px) saturate(180%)!important;
}
.sully-chat-composer {min-width:0!important;gap:6px!important;align-items:center!important;}
.sully-chat-input-wrap {
  min-width:0!important;flex:1 1 0%!important;
  background:transparent!important;border:0!important;
  border-radius:24px!important;box-shadow:none!important;
  backdrop-filter:none!important;
}
.sully-chat-textarea {
  min-width:0!important;background:transparent!important;
  color:var(--faint-ink)!important;border:0!important;
  box-shadow:none!important;caret-color:#7d756f!important;
}
.sully-chat-textarea::placeholder {color:#00000059!important;}
.sully-chat-actions-button,.sully-chat-send-button {
  flex-shrink:0!important;border-radius:50%!important;
  color:#5b504a!important;
  background:#ffffff35!important;
  border:1px solid #ffffff55!important;
  box-shadow:none!important;
}
.sully-chat-emoji-suggestions,.sully-chat-panel {
  background:rgba(255,255,255,.95)!important;
  backdrop-filter:blur(20px)!important;
  -webkit-backdrop-filter:blur(20px)!important;
  border:1px solid #8c8c8c30!important;
  color:var(--faint-ink)!important;
}
/* 原作的图标贴图：替换对应原生 SVG 的可见图标，不额外增加第二个按钮；
   停止回复保留糯米机原有状态标识，麦克风继续可见可用。 */
.sully-chat-back {
  background-image:url("https://i.postimg.cc/x1x7X8xD/image.png")!important;
  background-size:60% 60%!important;
  background-position:center!important;
  background-repeat:no-repeat!important;
}
.sully-chat-back > svg {visibility:hidden!important;}
.sully-chat-trigger:not([title="停止生成"]) {
  background-image:url("https://i.postimg.cc/0y2F5DCz/image.png")!important;
  background-size:60% 60%!important;
  background-position:center!important;
  background-repeat:no-repeat!important;
}
.sully-chat-trigger:not([title="停止生成"]) > svg {visibility:hidden!important;}
.sully-chat-actions-button {
  background-image:url("https://i.postimg.cc/qMGWdjyD/image.png")!important;
  background-position:center!important;
  background-size:58% 58%!important;
  background-repeat:no-repeat!important;
}
.sully-chat-actions-button > svg {visibility:hidden!important;}
.sully-chat-input-wrap button[aria-label="表情面板"] {
  background:transparent url("https://i.postimg.cc/rwnbDsnc/image.png") center / 62% 62% no-repeat!important;
}
.sully-chat-input-wrap button[aria-label="表情面板"] > svg {visibility:hidden!important;}
/* 原 Netease 发送图在原生 Chromium 截图中未显示：
   不隐藏原生发送图标，避免产生不可见按钮或与其它装饰重叠。 */
.sully-chat-send-button[aria-label="发送文字"] {
  background-image:none!important;
}
.sully-chat-send-button[aria-label="发送文字"] > svg {visibility:visible!important;}

/* 原作双方相同的半透明磨砂材质；直接写在实际气泡钩子，替换旧皮肤而非另叠一层。 */
.sully-bubble-user,.sully-bubble-ai {
  position:relative;
  min-width:0;max-width:100%;
  color:var(--faint-ink)!important;
  background:var(--faint-glass)!important;
  background-image:none!important;
  border:1px solid var(--faint-edge)!important;
  padding:7px 11px!important;
  font-size:14px!important;line-height:1.35!important;
  border-radius:16px!important;
  box-shadow:none!important;text-shadow:none!important;
  backdrop-filter:blur(16px) saturate(160%)!important;
  -webkit-backdrop-filter:blur(16px) saturate(160%)!important;
  overflow-wrap:anywhere;word-break:break-word;
}
.sully-bubble-user {border-radius:16px 16px 4px 16px!important;}
.sully-bubble-ai {border-radius:16px 16px 16px 4px!important;}
.sully-bubble-user a,.sully-bubble-ai a {color:#00376b!important;}
.sully-chat-message-content {min-width:0;overflow-wrap:anywhere;}
.sully-chat-message-sender {color:var(--faint-muted)!important;}
.sully-chat-message-avatar-img {border-radius:50%!important;}
/* 语音条沿用原有播放、暂停、字幕 DOM，仅换材质。 */
.sully-voice-bar {
  color:var(--faint-ink)!important;
  background:var(--faint-glass)!important;
  border:1px solid var(--faint-edge)!important;
  border-radius:16px!important;box-shadow:none!important;
  backdrop-filter:blur(16px) saturate(160%)!important;
}
.sully-voice-bar-button {color:#4a413a!important;background:#ffffff72!important;border-radius:50%!important;}
.sully-voice-bar-wave-segment {background:#827b75!important;}
.sully-voice-bar-toggle {color:#665d55!important;background:#ffffff49!important;}
.sully-voice-bar-transcript {color:var(--faint-ink)!important;background:#ffffff55!important;border:1px solid #8c8c8c40!important;border-radius:12px!important;}
/* 转账卡、回执、完成/退回/待收款一致；状态文字与收款/退回按钮保留。 */
.sully-chat-transfer-card,.sully-chat-transfer-receipt {
  min-width:0!important;max-width:min(100%,260px)!important;
  color:var(--faint-ink)!important;
  background:var(--faint-glass)!important;
  background-image:none!important;
  border:1px solid var(--faint-edge)!important;
  border-radius:16px!important;
  box-shadow:none!important;
  backdrop-filter:blur(16px) saturate(160%)!important;
  -webkit-backdrop-filter:blur(16px) saturate(160%)!important;
  overflow-wrap:anywhere;
}
.sully-chat-transfer-card {padding:12px 14px!important;}
.sully-chat-transfer-receipt {padding:9px 12px!important;}
.sully-chat-transfer-card[data-status],.sully-chat-transfer-receipt[data-status] {
  background:var(--faint-glass)!important;border-color:var(--faint-edge)!important;
}
.sully-chat-transfer-icon {
  color:#26262680!important;background:#ffffff55!important;
  border-radius:50%!important;
}
.sully-chat-transfer-header {border-bottom:1px solid #8c8c8c33!important;padding-bottom:7px!important;}
.sully-chat-transfer-amount {color:var(--faint-ink)!important;font-size:18px!important;font-weight:600!important;}
.sully-chat-transfer-brand,.sully-chat-transfer-note,.sully-chat-transfer-recipient,.sully-chat-transfer-status {
  color:var(--faint-muted)!important;
}
.sully-chat-transfer-status {background:#ffffff5c!important;}
.sully-chat-transfer-watermark {color:#262626!important;opacity:.14!important;}
/* 群聊红包、领取回执也归入同一份白框美化，不叠加独立浮层。 */
.sully-chat-group-root .sully-chat-group-packet,
.sully-chat-group-root .sully-chat-group-packet-receipt {
  color:var(--faint-ink)!important;
  background:var(--faint-glass)!important;
  background-image:none!important;
  border:1px solid var(--faint-edge)!important;
  border-radius:16px!important;
  box-shadow:none!important;
  backdrop-filter:blur(16px) saturate(160%)!important;
  -webkit-backdrop-filter:blur(16px) saturate(160%)!important;
}
.sully-chat-group-root .sully-chat-group-packet * {color:inherit;}
.sully-chat-system,.sully-chat-interaction {
  color:#615a55!important;background:#ffffff54!important;
  border:1px solid #8c8c8c36!important;border-radius:12px!important;
}
@media(max-width:380px) {
  .sully-chat-root:not(.sully-chat-group-root) .sully-chat-header:has(.sully-chat-back.absolute) .sully-chat-name::after {width:42px;height:42px;top:-51px;left:calc(50% + 4px);}
  .sully-chat-header .sully-chat-name {font-size:16px!important;}
  .sully-chat-back,.sully-chat-trigger {width:36px!important;height:36px!important;min-width:36px!important;min-height:36px!important;}
}
@media(prefers-reduced-motion:reduce) {
  .sully-chat-root .sully-chat-header,.sully-chat-root .sully-chat-inputbar {transition:none!important;}
}
